// spec: .qa/e2e/specs/summary.md
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, slide } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });
test.setTimeout(120_000);

test.describe('Сводка мониторинга', () => {
  test('Сводка без событий: длительность, дети справа RTL, «בלי אירועים», «חזרה לבית» #25e8f258 @iphone @data', async ({ page }) => {
    // 1. startMonitoring(page, 'calm') — дождаться /monitor/live
    await startMonitoring(page, 'calm');

    // 2. Полный свайп «כבה את המצלמה» — дождаться /monitor/summary
    await slide(page, 'כבה את המצלמה');
    await page.waitForURL(/\/monitor\/summary/, { timeout: 15_000 });
    await expect(page).toHaveURL(/\/monitor\/summary/);

    // 3. Проверить заголовок, интервал времени, строку детей и блок «מה קרה»
    await expect(page.getByRole('heading', { name: /\d+ דק׳/ }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText(/\d{1,2}:\d{2}\s*[–-]\s*\d{1,2}:\d{2}/).filter({ visible: true }).first()).toBeVisible();

    const kids = page.getByText(/QA בדיקה.*ו-.*QA קטן.*היו בבריכה/).filter({ visible: true }).last();
    await expect(kids).toBeVisible();
    expect(await kids.evaluate((el) => getComputedStyle(el).direction)).toBe('rtl');
    // Аватары прижаты к правому краю, текст идёт слева от них (RTL)
    const geo = await kids.evaluate((el) => {
      const text = el.getBoundingClientRect();
      const avatars = el.parentElement!.firstElementChild!.getBoundingClientRect();
      return { textRight: text.right, avatarsLeft: avatars.left, avatarsRight: avatars.right, width: window.innerWidth };
    });
    expect(geo.width - geo.avatarsRight).toBeLessThan(geo.avatarsLeft);
    expect(geo.textRight).toBeLessThanOrEqual(geo.avatarsLeft + 1);

    await expect(page.getByRole('heading', { name: /בלי אירועים/ }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('בלי התרעות').filter({ visible: true })).toBeVisible();
    await expect(page.getByText('התחלת ניטור', { exact: true }).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('הניטור הסתיים', { exact: true }).filter({ visible: true })).toBeVisible();

    await expect(page.getByRole('button', { name: 'לכל הניטורים' }).filter({ visible: true })).toBeVisible();

    // 4. Нажать «חזרה לבית»
    await page.getByRole('button', { name: 'חזרה לבית' }).filter({ visible: true }).click();
    await page.waitForURL(/\/home/);
    await expect(page).toHaveURL(/\/home/);
  });
});
